buttonColor:
{{
  (() => {
    const item = typeof currentItem !== 'undefined' ? currentItem : null;
    if (!item || item.isHeader) return "#E0E0E0";

    const daten = Bewaesserung_Lesen.data || [];
    const rawVentil = item.Ventil ?? item.Ventil_Links ?? item.Ventil_Rechts ?? "";
    const aktivesVentil = String(rawVentil).trim();

    if (!aktivesVentil) return "#E0E0E0";

    const e = daten.findLast(row => {
      const vVal = String(row.Ventil || row.ventilName || "").trim();
      const status = String(row.Status || "").trim().toLowerCase();
      const matchesVentil = (vVal === aktivesVentil) || (!isNaN(parseFloat(vVal)) && !isNaN(parseFloat(aktivesVentil)) && parseFloat(vVal) === parseFloat(aktivesVentil));
      return matchesVentil && status !== "fertig";
    });

    if (!e || !e.Programm) return "#E0E0E0"; 

    const prog = String(e.Programm).trim().toLowerCase();
    switch (prog) {
      case "viel": return "#1d4ed8";
      case "wenig": return "#38bdf8";
      case "paletten": return "#f59e0b";
      case "topfen": return "#10b981";
      default: return "#E0E0E0";
    }
  })()
}}

onClick:
{{
  (async () => {
    const item = List_KlimaPC.triggeredItem;
    if (!item) return;

    // 1. Sofort lokal über den Data_Helper entfernen (verschwindet ohne Reload)
    const currentData = appsmith.store.lokaleBewaesserungData || Bewaesserung_Lesen.data;
    const rowIdx = await Data_Helper.entferneLokalenEintrag(item, currentData);

    // 2. Im Hintergrund Google Sheets synchronisieren
    if (rowIdx !== undefined) {
      await Bewaesserung_Update_Status.run({
        "realRowIndex": rowIdx
      });
    }
  })()
}}

text:
{{
  (() => {
    const item = typeof currentItem !== 'undefined' ? currentItem : null;
    if (!item) return "";
    if (item.isHeader) return item.titel || "";
    return item.bahn ? "Bahn " + item.bahn + "     •      " + item.Ventil : item.Ventil || "";
  })()
}}
